package io.github.ningpp.compat;

import java.util.Arrays;

/** Replacement for System.MemoryExtensions (generated by CSharpToJava converter). */
public class MemoryExtensions {
    /** C# string.AsSpan() → ReadOnlySpan&lt;Character&gt; (converter maps char → Character). */
    public static ReadOnlySpan<Character> asSpan(String s) {
        if (s == null) return new ReadOnlySpan<>(new Character[0]);
        Character[] arr = new Character[s.length()];
        for (int i = 0; i < s.length(); i++) {
            arr[i] = s.charAt(i);
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# string.AsSpan(start, length) → ReadOnlySpan&lt;Character&gt;. */
    public static ReadOnlySpan<Character> asSpan(String s, int start, int length) {
        if (s == null) return new ReadOnlySpan<>(new Character[0]);
        Character[] arr = new Character[length];
        for (int i = 0; i < length; i++) {
            arr[i] = s.charAt(start + i);
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# string.AsSpan(start) → ReadOnlySpan&lt;Character&gt; (slice from start to end). */
    public static ReadOnlySpan<Character> asSpan(String s, int start) {
        return asSpan(s, start, s.length() - start);
    }

    /** C# string.AsMemory() → Java ReadOnlyMemory<Character> */
    public static ReadOnlyMemory<Character> asMemory(String s) {
        return ReadOnlyMemory.fromString(s);
    }

    /** C# string.AsMemory(start) → Java ReadOnlyMemory<Character> (slice from start to end) */
    public static ReadOnlyMemory<Character> asMemory(String s, int start) {
        return ReadOnlyMemory.fromString(s, start, s.length() - start);
    }

    /** C# string.AsMemory(start, length) → Java ReadOnlyMemory<Character> */
    public static ReadOnlyMemory<Character> asMemory(String s, int start, int length) {
        return ReadOnlyMemory.fromString(s, start, length);
    }

    /** C# char[].AsMemory() → Java ReadOnlyMemory<Character> */
    public static ReadOnlyMemory<Character> asMemory(char[] data) {
        if (data == null) return new ReadOnlyMemory<>();
        Character[] arr = new Character[data.length];
        for (int i = 0; i < data.length; i++) {
            arr[i] = data[i];
        }
        return new ReadOnlyMemory<>(arr);
    }

    /** C# char[].AsMemory(start, length) → Java ReadOnlyMemory<Character> */
    public static ReadOnlyMemory<Character> asMemory(char[] data, int start, int length) {
        if (data == null) return new ReadOnlyMemory<>();
        Character[] arr = new Character[length];
        for (int i = 0; i < length; i++) {
            arr[i] = data[start + i];
        }
        return new ReadOnlyMemory<>(arr, 0, length);
    }

    /** C# Span<byte> → Java ReadOnlySpan<Integer> (matches converter's byte→Integer mapping) */
    public static ReadOnlySpan<Integer> asSpan(byte[] data) {
        if (data == null) return new ReadOnlySpan<>(new Integer[0]);
        Integer[] arr = new Integer[data.length];
        for (int i = 0; i < data.length; i++) {
            arr[i] = data[i] & 0xFF;
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# ReadOnlySpan<byte> slice → Java ReadOnlySpan<Integer> (matches converter's byte→Integer mapping) */
    public static ReadOnlySpan<Integer> asSpan(byte[] data, int start, int length) {
        if (data == null) return new ReadOnlySpan<>(new Integer[0]);
        Integer[] arr = new Integer[length];
        for (int i = 0; i < length; i++) {
            arr[i] = data[start + i] & 0xFF;
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# T[].AsSpan() → Span&lt;T&gt; for reference-type arrays (e.g. string[] capslist).
     *  Primitive char[]/byte[] arrays bind to their more specific overloads. */
    @SuppressWarnings("unchecked")
    public static <T> Span<T> asSpan(T[] data) {
        return new Span<>(data == null ? (T[]) new Object[0] : data);
    }

    /** C# char[].AsSpan() → ReadOnlySpan&lt;Character&gt;. */
    public static ReadOnlySpan<Character> asSpan(char[] data) {
        if (data == null) return new ReadOnlySpan<>(new Character[0]);
        Character[] arr = new Character[data.length];
        for (int i = 0; i < data.length; i++) {
            arr[i] = data[i];
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# char[].AsSpan(start, length) → ReadOnlySpan&lt;Character&gt;. */
    public static ReadOnlySpan<Character> asSpan(char[] data, int start, int length) {
        if (data == null) return new ReadOnlySpan<>(new Character[0]);
        Character[] arr = new Character[length];
        for (int i = 0; i < length; i++) {
            arr[i] = data[start + i];
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# char[].AsSpan(start) → ReadOnlySpan&lt;Character&gt; (slice from start to end). */
    public static ReadOnlySpan<Character> asSpan(char[] data, int start) {
        return asSpan(data, start, data.length - start);
    }

    /** C# byte[].AsSpan(start) → ReadOnlySpan&lt;Integer&gt; (slice from start to end). */
    public static ReadOnlySpan<Integer> asSpan(byte[] data, int start) {
        return asSpan(data, start, data.length - start);
    }

    /** C# Span<T>.Reverse() / MemoryExtensions.Reverse(Span<T>) — reverses in place. */
    public static <T> void reverse(Span<T> span) {
        int i = 0;
        int j = span.length() - 1;
        while (i < j) {
            T tmp = span.get(i);
            span.set(i, span.get(j));
            span.set(j, tmp);
            i++;
            j--;
        }
    }

    /** C# ReadOnlySpan<T>.SequenceEqual(ReadOnlySpan<T>) — element-wise equality. */
    public static <T> boolean sequenceEqual(ReadOnlySpan<T> left, ReadOnlySpan<T> right) {
        if (left == null || right == null) return left == right;
        if (left.length() != right.length()) return false;
        for (int i = 0; i < left.length(); i++) {
            if (!java.util.Objects.equals(left.get(i), right.get(i))) return false;
        }
        return true;
    }

    /** C# MemoryExtensions.IndexOf(ReadOnlySpan&lt;char&gt;, char) — first index or -1. */
    public static int indexOf(ReadOnlySpan<Character> span, Character value) {
        if (span == null || value == null) return -1;
        for (int i = 0; i < span.length(); i++) {
            if (span.get(i).equals(value)) return i;
        }
        return -1;
    }

    /** C# MemoryExtensions.IndexOf(ReadOnlySpan&lt;char&gt;, char) with a primitive char. */
    public static int indexOf(ReadOnlySpan<Character> span, char value) {
        return indexOf(span, Character.valueOf(value));
    }

    /** C# MemoryExtensions.IndexOf(ReadOnlySpan&lt;int&gt;, int) — first index or -1. */
    public static int indexOf(ReadOnlySpan<Integer> span, Integer value) {
        if (span == null || value == null) return -1;
        for (int i = 0; i < span.length(); i++) {
            if (span.get(i).equals(value)) return i;
        }
        return -1;
    }

    /**
     * C# MemoryExtensions.ToLower(ReadOnlySpan&lt;char&gt;, Span&lt;char&gt;, CultureInfo):
     * lowercases each source char into the destination span and returns the number
     * of chars written.
     */
    public static int toLowerCase(ReadOnlySpan<Character> source, Span<Character> destination, CultureInfo culture) {
        int count = 0;
        for (int i = 0; i < source.length(); i++) {
            char c = source.get(i);
            char lowered = Character.toLowerCase(c);
            destination.set(count, lowered);
            count++;
        }
        return count;
    }

}
